use agmp_native_protocol::JavaRuntimeInfo;use std::{path::PathBuf,process::Command};
pub fn inspect_java(managed:&std::path::Path)->JavaRuntimeInfo{let mut c=Vec::new();if let Ok(home)=std::env::var("JAVA_HOME"){let mut p=PathBuf::from(home);p.push("bin");p.push(if cfg!(windows){"java.exe"}else{"java"});c.push((p.to_string_lossy().into_owned(),"JAVA_HOME".to_string()))}if let Ok(rd)=std::fs::read_dir(managed.join("java")){for e in rd.flatten(){let p=e.path().join("bin").join(if cfg!(windows){"java.exe"}else{"java"});if p.exists(){c.push((p.to_string_lossy().into_owned(),"AGMP managed".into()))}}}c.push(("java".into(),"PATH".into()));for(exe,source)in c{if let Ok(o)=Command::new(&exe).arg("-version").output(){if o.status.success(){let t=format!("{}{}",String::from_utf8_lossy(&o.stderr),String::from_utf8_lossy(&o.stdout));let ver=extract(&t);let major=major(&ver);if major>0{return JavaRuntimeInfo{available:true,executable:exe,major,version:ver,source,error:String::new()}}}}}JavaRuntimeInfo{available:false,executable:String::new(),major:0,version:String::new(),source:String::new(),error:"No usable JAVA_HOME/PATH/managed Java".into()}}
fn extract(t:&str)->String{if let Some(s)=t.find('"'){if let Some(e)=t[s+1..].find('"'){return t[s+1..s+1+e].to_string()}}String::new()}fn major(v:&str)->u32{let p=v.split(['.','_','-']).collect::<Vec<_>>();if p.first()==Some(&"1"){p.get(1).and_then(|x|x.parse().ok()).unwrap_or(0)}else{p.first().and_then(|x|x.parse().ok()).unwrap_or(0)}}
